  'integrations.proxy': 'Outgoing proxy',
  'integrations.proxyDescription':
    'Carries this server\u2019s own SMTP conversation out through another address. The relay below answers the same question differently \u2014 it hands the message to somebody else\u2019s mail server; this one still delivers by MX lookup, just from somewhere else. Either is an answer to a blocked or blocklisted port 25, and neither needs the other.',
  'integrations.proxySocks5': 'SOCKS5 proxy',
  'integrations.proxyHelp': 'As host:port. Empty means outgoing mail leaves this machine directly.',

  'integrations.relay': 'Outgoing relay',
  'integrations.relayDescription':
    'Hand outgoing mail to one mail server instead of delivering it by MX lookup. Almost every domestic ISP blocks outbound port 25, and a relay is reached on a submission port instead. It is also how this server sends through a provider: SES, Postmark and Resend all offer an SMTP endpoint, and the message arrives carrying the signature this server already applied.',
